#include <stdio.h>

int main(void) {
    int N, F;
    scanf("%d %d", &N, &F);

    char g[500][501];

    for (int i = 0; i < N; i++) {
        scanf("%s", g[i]);
    }

    if (g[0][0] - '0' <= F) {
        int qx[250000], qy[250000];
        int head = 0, tail = 0;

        qx[tail] = 0;
        qy[tail] = 0;
        tail++;
        g[0][0] = '*';

        int dx[4] = {1, -1, 0, 0};
        int dy[4] = {0, 0, 1, -1};

        while (head < tail) {
            int x = qx[head];
            int y = qy[head];
            head++;

            for (int d = 0; d < 4; d++) {
                int nx = x + dx[d];
                int ny = y + dy[d];

                if (nx >= 0 && nx < N && ny >= 0 && ny < N && g[nx][ny] != '*') {
                    if (g[nx][ny] - '0' <= F) {
                        g[nx][ny] = '*';
                        qx[tail] = nx;
                        qy[tail] = ny;
                        tail++;
                    }
                }
            }
        }
    }

    for (int i = 0; i < N; i++) {
        printf("%s\n", g[i]);
    }

    return 0;
}
